struct Order {
    let customerId: CustomerId
    private(set) var lines: [Line] = []
    private(set) var total: Money = .zero

    mutating func add(_ line: Line) throws {          // value semantics: mutates the copy
        let next = total + line.price
        guard next <= .limit else { throw OrderError.limitExceeded }
        lines.append(line)
        total = next
    }
}
